{
  "headline": "FDA's records trace our supply to a plant classified OAI 618 days before the posting",
  "headline_cites": ["D7"],
  "sentences": [
    {
      "text": "FDA lists ketamine hydrochloride as To Be Discontinued with an initial posting date of 2018-02-16.",
      "cites": ["D13"]
    },
    {
      "text": "A registered plant on our labels, Hospira, Inc. (FEI 1925262), received an OAI classification from inspection 976095 ending 2016-06-08, which was 618 days before the shortage posting.",
      "cites": ["D7", "E14", "E20"]
    },
    {
      "text": "The same plant later received a Warning Letter on 2017-02-14 (367 days before posting) and another OAI classification from inspection 1064827 ending 2018-08-15 (180 days after posting).",
      "cites": ["D8", "D10", "E19", "E16"]
    },
    {
      "text": "Corvale East holds 39 vials of the 50 mg/mL, 10 mL presentation at 7.2 vials per day, providing 5.4 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 126 vials of the same presentation at 7.7 vials per day, providing 16.4 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The top-ranked option is to transfer 18 vials of 50 mg/mL, 10 mL from Corvale General to Corvale East, which would raise Corvale East to 8 days on hand while Corvale General retains two weeks of supply.",
      "cites": ["D14"]
    }
  ]
}
